INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-desafio-de-la-escultura-humana', 'El Desafío de la Escultura Humana', 'Dinámica de imaginación corporal y trabajo en equipo donde los grupos de scouts representan objetos, máquinas y estructuras uniendo sus propios cuerpos.', '<h2>📜 Descripción de El Desafío de la Escultura Humana</h2>
<p><b>El Desafío de la Escultura Humana</b> es una dinámica de expresión corporal, improvisación colectiva y sinergia scout. En esta actividad, los beneficiarios se organizan en patrullas o seisenas y reciben el reto de representar objetos cotidianos, animales, monumentos o máquinas complejas (ej. un reloj de pared, un automóvil, una fogata o un elefante) utilizando exclusivamente la articulación y combinación de sus propios cuerpos en un tiempo límite de 30 segundos.</p>
<p>Esta dinámica fomenta el pensamiento lateral, la desinhibición postural y la cooperación de grupo en la Manada, Compañía y Tropa.</p>

<h2>🎲 ¿Cómo se juega El Desafío de la Escultura Humana?</h2>
<p>Para llevar a cabo la dinámica con ritmo y entusiasmo, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Formación de Equipos:</b> Los participantes se organizan en grupos de 4 a 6 scouts y se ubican en su zona del terreno de juego.</li>
  <li><b>Anuncio del Desafío:</b> El animador o dirigente nombra en voz alta el objeto o estructura a construir (ej. <i>¡Tienen 30 segundos para construir un reloj de péndulo!</i>).</li>
  <li><b>Construcción Colectiva:</b> Los scouts deben comunicarse rápidamente y acoplar sus cuerpos (de pie, agachados o en el suelo) para formar la escultura viviente antes de que venza la cuenta regresiva.</li>
  <li><b>Evaluación y Movimiento:</b> A la señal de ¡Tiempo!, las esculturas deben congelar su posición durante 10 segundos. Si el objeto lo requiere, el dirigente puede pedir que la escultura ejecute un movimiento coordinado (ej. las agujas del reloj o el motor del vehículo).</li>
  <li><b>Rotación de Desafíos:</b> Se presentan sucesivos objetos aumentando gradualmente la complejidad de las estructuras humanas.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Desafío de la Escultura Humana</h2>
<p>Al ser una dinámica de cooperación plástica, el sistema de puntuación reconoce el esfuerzo colectivo en el Tally:</p>
<ul>
  <li><b>Escultura Más Creativa:</b> Otorgar 5 puntos al equipo que logre la representación plástica más original e ingeniosa del objeto ordenado.</li>
  <li><b>Sincronización y Rapidez:</b> Otorgar 3 puntos a la patrulla que logre acoplar sus cuerpos con mayor velocidad antes del límite de tiempo.</li>
  <li><b>Espíritu de Sinergia:</b> Otorgar 3 puntos a la unidad donde participen activamente todos los integrantes en el ensamble corporal.</li>
</ul>', '/uploads/el-desafio-de-la-escultura-humana.webp', 'publicado', '{"areas": ["creatividad", "corporalidad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Exterior"], "materiales": ["Sin Materiales"], "objetivos": ["Estimular la creatividad e imaginación", "Desarrollo de la expresión corporal", "Favorecer el trabajo en equipo", "Fomentar la cooperación"], "justificacion_areas": "El Desafío de la Escultura Humana ejercita la creatividad al exigir la traducción simbólica de objetos tridimensionales utilizando el cuerpo como materia prima. Desarrolla la corporalidad promoviendo la tonicidad muscular, el equilibrio dinámico y la flexibilidad postural. Fortalece la sociabilidad al requerir la negociación directa y la coordinación física inmediata entre todos los miembros de la patrulla.", "variaciones": "<b>Esculturas con Movimiento Cinético:</b> Exigir que la estructura corporal humana realice una función mecánica sincronizada (ej. un engranaje girando o un tren en marcha).<br><b>Cadena Narrativa de Objetos:</b> Cada objeto construido por la patrulla debe estar vinculado temáticamente con el objeto producido por el equipo anterior.<br><b>Desafío a Ciegas:</b> Un participante de la patrulla actúa con ojos vendados y sus compañeros deben guiar la posición de sus extremidades para integrarlo a la figura.", "recomendaciones": "Asegurar que la actividad se realice en una superficie acolchada o sobre césped blando para proteger a los beneficiarios durante las posturas a nivel de piso. Mantener un clima de ánimo festivo y libre de críticas para afianzar la seguridad emocional de todos los participantes. Adaptar el tiempo de construcción según el tamaño y edad de las unidades.", "objetivos_educativos": [{"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "unidad": "Manada", "texto": "Me gusta participar en juegos de observación.", "como_se_cumple": "Observando las proporciones del objeto para diseñar la escultura corporal."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "unidad": "Manada", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "como_se_cumple": "Improvisando con agilidad soluciones fisicas para acoplarme a la escultura."}, {"id": "e1b7276f-4fd2-4c39-a32a-bd7fadbee702", "area": "Creatividad", "unidad": "Compañía", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Proponiendo ideas creativas de distribución postural en el equipo."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Visualizando el ensamblaje tridimensional del grupo desde fuera."}, {"id": "49ae6ac6-be8f-4f2c-8b3e-6711d041181f", "area": "Creatividad", "unidad": "Tropa", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Aportando soluciones de diseño anatómico innovadoras a la patrulla."}, {"id": "3d0dff9b-11cd-4a30-b3a6-ec011ad95062", "area": "Creatividad", "unidad": "Tropa", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Sintetizando formas abstractas para componer figuras mecánicas complejas."}, {"id": "a0c0e5c9-aba9-43be-8ce2-53bc4ede06b5", "area": "Corporalidad", "unidad": "Manada", "texto": "Me gusta practicar deportes.", "como_se_cumple": "Ejercitando el equilibrio estático y el tono muscular en posturas de sostenimiento."}, {"id": "309c6121-94fc-43a2-b0fb-f6a975f78962", "area": "Corporalidad", "unidad": "Manada", "texto": "Practico deportes, conozco sus reglas y sé perder.", "como_se_cumple": "Afinando la flexibilidad articular y la resistencia en el mantenimiento del equilibrio."}, {"id": "1427451e-b8b3-493b-8525-e53298381e07", "area": "Corporalidad", "unidad": "Compañía", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "como_se_cumple": "Respetando las limitaciones físicas propias y de los compañeros durante el esfuerzo."}, {"id": "b12da732-d736-480c-82b8-95b312316390", "area": "Corporalidad", "unidad": "Compañía", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "como_se_cumple": "Exigiendo precisión y fuerza en las posturas corporales combinadas."}, {"id": "0765469b-caef-4457-9d6b-cb739c855402", "area": "Corporalidad", "unidad": "Tropa", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "como_se_cumple": "Desarrollando la motricidad gruesa y la estabilidad biomecánica grupal."}, {"id": "08369c53-2c02-4e9c-8bb5-f949cd092c98", "area": "Corporalidad", "unidad": "Tropa", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "como_se_cumple": "Perfeccionando la resistencia kinésica para sostener esculturas complejas."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando los tiempos de construcción y las normas de apoyo físico seguro."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Aceptando el rol y posición asignada dentro de la escultura por la seisena."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Promoviendo el cuidado respetuoso del espacio personal durante los acoplamientos."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Fomentando la cooperación fraterna y el trabajo coordinado de la patrulla."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Acatando las decisiones colectivas de diseño y apoyando la estructura de los pares."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Fortaleciendo la cohesión y el apoyo mutuo en las actividades de equipo."}]}'::jsonb, NOW(), NOW(), NULL, NULL
